#!/bin/sh
# Seed Kirk's configuration on first start, then run Apache.
#
# /data is the app's persistent data folder (APP_DATA_DIR/data - the folder
# shown in umbrelOS's Files manager). conf.php is persisted there and copied
# into the web root as a real file on every start, so the web root never
# depends on symlinks or mount internals.

log() { echo "[kirk-entrypoint] $*"; }

CONF_SRC=/data/conf.php
CONF_DST=/var/www/html/conf.php

render_conf() {
  cat <<EOF
<?php
/**
 * Kirk conf.php - generated by the umbrelOS package on first start.
 *
 * The persisted copy lives at data/conf.php in the app's storage
 * (Files -> Apps -> Kirk -> data). Edit it there and restart the
 * app to apply. Full option reference: conf.php.sample in the install.
 */

// Human-readable system name, shown in the interface and emails.
define('SYSTEM_NAME', 'Kirk');

// Database (the bundled MariaDB service)
define('DB_HOST', '${KIRK_DB_HOST}');
define('DB_TYPE', 'mysql');
define('DB_DATABASE', '${KIRK_DB_NAME}');
define('DB_USERNAME', '${KIRK_DB_USER}');
define('DB_PASSWORD', '${KIRK_DB_PASSWORD}');
EOF
}

if [ -f "$CONF_SRC" ]; then
  log "Using persisted config at $CONF_SRC"
elif [ -d "$CONF_SRC" ]; then
  # A previously failed mount can leave a directory where the file belongs.
  log "$CONF_SRC is a directory - replacing it with a file"
  rm -rf "$CONF_SRC" || true
fi

if [ -f "$CONF_SRC" ]; then
  cp -f "$CONF_SRC" "$CONF_DST" && log "Copied persisted config into the web root" || log "WARNING: could not copy config into web root"
else
  log "Seeding new config at $CONF_SRC"
  mkdir -p /data 2>/dev/null || true
  render_conf > "$CONF_SRC" 2>/dev/null && log "Persisted config written" || log "WARNING: could not persist config to /data"
  if [ -f "$CONF_SRC" ]; then
    cp -f "$CONF_SRC" "$CONF_DST" || true
  else
    # Last resort: render a runtime-only config straight into the web root
    # so Kirk can still boot (settings would reset on container recreation).
    log "WARNING: writing runtime-only config (not persisted)"
    render_conf > "$CONF_DST"
  fi
fi

chmod 644 "$CONF_DST" 2>/dev/null || true
chown www-data:www-data "$CONF_DST" 2>/dev/null || true

# Uploads live in persistent storage, bind-mounted straight into the web root.
mkdir -p /data/files 2>/dev/null || true
chown -R www-data:www-data /data/files 2>/dev/null || true
chown www-data:www-data /var/www/html/files 2>/dev/null || true

log "Config ready - starting Apache"
exec "$@"
